        * {{ margin: 0; padding: 0; box-sizing: border-box; }}
        html {{ color-scheme: light dark; }}
        body {{
            font-family: ""YS Text"", -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
            background-color: var(--id-color-surface-submerged);
            color: var(--id-color-text-primary);
            line-height: 1.5;
            min-height: 100vh;
            transition: background-color 0.3s ease, color 0.3s ease;
        }}
        .app-shell_root__mG_ht {{ display: flex; flex-direction: column; min-height: 100vh; }}
        .app-shell_content___V8RK {{ flex-grow: 1; display: flex; justify-content: center; align-items: center; padding: 24px; }}

        /* Mimic Yandex Header */
        .navbar {{
            display: flex; justify-content: space-between; align-items: center;
            height: 56px; padding: 0 24px;
            background-color: var(--id-color-surface-elevated-0);
            box-shadow: var(--id-effect-shadow-elevated-50);
            position: sticky; top: 0; z-index: 10;
        }}
        .logo {{
            display: flex; align-items: center;
            text-decoration: none;
            color: var(--id-color-text-primary);
        }}
        .logo svg path {{ fill: var(--yandex-primary-color); }}
        [data-theme=""dark""] .logo svg path {{ fill: var(--id-color-text-primary); }}

        .theme-toggle {{
            background: none; border: none; cursor: pointer; font-size: 20px;
            color: var(--id-color-text-secondary); padding: 8px; border-radius: 50%;
            transition: background-color 0.15s ease-in-out, color 0.15s ease-in-out;
        }}
        .theme-toggle:hover {{ background-color: var(--id-color-default-bg-hovered); color: var(--id-color-text-primary); }}

        /* Centered Container for Auth Forms */
        .container {{ max-width: 420px; width: 100%; margin: 0 auto; }}

        /* Yandex-like Card */
        .card {{
            background-color: var(--id-color-surface-elevated-0);
            border-radius: var(--id-card-border-radius, 24px);
            box-shadow: var(--id-effect-shadow-elevated-50);
            overflow: hidden;
            transition: background-color 0.3s ease;
        }}
        .card-header {{ padding: 24px 24px 16px; border-bottom: 1px solid var(--id-color-line-normal); }}
        .card-body {{ padding: 24px; }}
        .card-footer {{ padding: 16px 24px; border-top: 1px solid var(--id-color-line-normal); display: flex; justify-content: space-between; align-items: center; }}

        /* Typography */
        h1, h2, h3, h4, h5, h6 {{ font-family: ""YS Text"", Arial, sans-serif; color: var(--id-color-text-primary); margin-bottom: 8px; }}
        h1 {{ font: var(--id-typography-heading-m); font-weight: 500; }} /* Adjusted to match login header */
        p {{ margin-bottom: 16px; color: var(--id-color-text-secondary); font: var(--id-typography-text-m); }}

        /* Forms */
        .form-group {{ margin-bottom: 20px; }}
        label {{ display: block; margin-bottom: 8px; font: var(--id-typography-text-s); color: var(--id-color-text-secondary); font-weight: 500; }}
        input, select, textarea {{
            width: 100%;
            height: var(--id-textfield-height, 48px);
            padding: 0 20px; /* Adjusted padding */
            border: none; /* Removed default border */
            border-radius: var(--id-textfield-border-radius, 16px);
            font: var(--id-typography-text-m);
            background-color: var(--id-color-default-bg-base);
            color: var(--id-color-text-primary);
            box-shadow: inset 0 0 0 2px transparent; /* Prepare for focus */
            transition: background-color 0.15s ease-in-out, box-shadow 0.15s ease-in-out;
        }}
         input:-webkit-autofill,
         input:-webkit-autofill:hover,
         input:-webkit-autofill:focus,
         input:-webkit-autofill:active {{
            -webkit-box-shadow: 0 0 0 30px var(--id-color-default-bg-base) inset !important;
            -webkit-text-fill-color: var(--id-color-text-primary) !important;
            transition: background-color 5000s ease-in-out 0s; /* Override autofill styles */
         }}
        input:focus, select:focus, textarea:focus {{
            outline: none;
            background-color: var(--id-color-surface-elevated-0);
            box-shadow: inset 0 0 0 2px var(--id-color-brand-border);
        }}
        textarea {{ height: auto; min-height: 100px; padding: 14px 20px; }}

        /* Buttons */
        button, .btn {{
            display: inline-flex; justify-content: center; align-items: center;
            height: var(--id-button-height, 48px);
            padding: 0 20px; /* Adjusted padding */
            border: none;
            border-radius: var(--id-button-radius, 16px);
            font: var(--id-typography-text-m); font-weight: 500;
            cursor: pointer; text-decoration: none; text-align: center;
            transition: background-color 0.15s ease-in-out, color 0.15s ease-in-out;
            -webkit-tap-highlight-color: transparent;
            background-color: var(--yandex-primary-color); /* Primary Yandex color */
            color: #fff;
        }}
        button:hover, .btn:hover {{ background-color: var(--yandex-primary-color-hover); }}
        button:active, .btn:active {{ background-color: var(--yandex-primary-color-active); }}
        .btn-secondary {{
            background-color: var(--id-color-default-bg-base);
            color: var(--id-color-text-primary);
        }}
        .btn-secondary:hover {{ background-color: var(--id-color-default-bg-hovered); }}
        .btn-secondary:active {{ background-color: var(--id-color-default-bg-pressed); }}
        .btn-block {{ display: flex; width: 100%; }}

        /* Messages */
        .error-message, .success-message {{
            padding: 12px 16px;
            border-radius: 16px;
            margin-bottom: 20px;
            font: var(--id-typography-text-s);
            display: flex; align-items: center; gap: 8px;
        }}
        .error-message {{ background-color: var(--id-color-status-negative-soft); color: var(--id-color-status-negative); }}
        .success-message {{ background-color: var(--id-color-status-positive-soft); color: var(--id-color-status-positive); }}

        /* QR Code & Code Display */
        .qr-code {{ display: flex; justify-content: center; margin: 24px 0; }}
        .qr-code img {{ max-width: 200px; height: auto; border-radius: 16px; background-color: #fff; padding: 8px; box-shadow: var(--id-effect-shadow-elevated-50); }}
        .code-display {{
            font-family: monospace;
            background-color: var(--id-color-default-bg-base);
            padding: 12px 16px;
            border-radius: 16px;
