         <svg aria-hidden=""true"" focusable=""false"" height=""28"" viewBox=""0 0 62 30"" width=""62""><circle cx=""15"" cy=""14.9998"" r=""15"" fill=""var(--yandex-primary-color)""></circle><path d=""M17.2116 8.40037H15.6936C13.0912 8.40037 11.7899 9.70158 11.7899 11.6534C11.7899 13.8221 12.6574 14.9064 14.6092 16.2076L16.1273 17.2919L11.7899 24.0148H8.32007L12.4405 17.9425C10.055 16.2076 8.7538 14.6895 8.7538 11.8703C8.7538 8.40037 11.1393 6.01483 15.6936 6.01483H20.2478V24.0148H17.2116V8.40037Z"" fill=""#fff""></path></svg>
         <span style=""font-weight: 500; font-size: 18px; margin-left: 8px;"">BRU AVTOPARK</span>
       </a>
       <button class=""theme-toggle"" id=""themeToggle"" aria-label=""Toggle theme"">🌙</button>
     </header>
     <main class=""app-shell_content___V8RK"">
        <div class=""container fade-in"">
             {1} {/* Content is inserted here */}
        </div>
     </main>
    </div>
    <script>
        const themeToggleBtn = document.getElementById('themeToggle');
        const body = document.body;
        const prefersDarkScheme = window.matchMedia('(prefers-color-scheme: dark)');

        function applyTheme(theme) {{
            body.setAttribute('data-theme', theme);
            themeToggleBtn.textContent = theme === 'dark' ? '☀️' : '🌙';
            localStorage.setItem('theme', theme);
        }}

        const savedTheme = localStorage.getItem('theme');
        const initialTheme = savedTheme || (prefersDarkScheme.matches ? 'dark' : 'light');
        applyTheme(initialTheme);

        themeToggleBtn.addEventListener('click', () => {{
            const newTheme = body.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
            applyTheme(newTheme);
        }});

        prefersDarkScheme.addEventListener('change', (e) => {{
             // Only change if no theme is explicitly saved by the user
             if (!localStorage.getItem('theme')) {{
                 applyTheme(e.matches ? 'dark' : 'light');
             }}
        }});

         // Helper function to convert ArrayBuffer to Base64 string (if needed by WebAuthn scripts)
        function arrayBufferToBase64(buffer) {{
            const bytes = new Uint8Array(buffer);
            let binary = '';
            for (let i = 0; i < bytes.byteLength; i++) {{
                binary += String.fromCharCode(bytes[i]);
            }}
            return btoa(binary);
        }}
    </script>
</body>
