                            <button class=""btn btn-secondary"" style=""width: 44px; height: 44px; padding: 0; border-radius: 50%;"" aria-label=""Google"">G</button>
                            <button class=""btn btn-secondary"" style=""width: 44px; height: 44px; padding: 0; border-radius: 50%;"" aria-label=""QR-код"">QR</button>
                            <button class=""btn btn-secondary"" style=""width: 44px; height: 44px; padding: 0; border-radius: 50%;"" aria-label=""Другие способы"">...</button>
