            <script>
                // Existing JavaScript for login form submission remains the same
                 function submitLoginForm() {{
                    document.getElementById('loginButton').disabled = true;
                    document.getElementById('statusDiv').innerHTML = '<div class=""loader""></div>';
                    const username = document.getElementById('username').value;
                    const password = document.getElementById('password').value;
                    fetch('/api/auth/login', {{
                        method: 'POST',
                        headers: {{ 'Content-Type': 'application/x-www-form-urlencoded' }},
                        body: `username=${{encodeURIComponent(username)}}&password=${{encodeURIComponent(password)}}`,
                        credentials: 'same-origin'
                    }})
                    .then(response => {{
                        if (response.redirected) {{ window.location.href = response.url; return; }}
                        // Check if response is JSON before parsing
                        const contentType = response.headers.get(""content-type"");
                        if (contentType && contentType.indexOf(""application/json"") !== -1) {{
                            return response.json();
                        }} else {{
                           // Handle non-JSON responses, maybe redirect or show generic error
                           throw new Error('Received non-JSON response from server.');
                        }}
                    }})
                    .then(data => {{
                         if (data && data.success && data.data && data.data.token) {{
                            localStorage.setItem('auth_token', data.data.token);
                            document.getElementById('statusDiv').innerHTML = '<p class=""success-message"">Вход успешен! Перенаправление...</p>';
                            setTimeout(() => {{ window.location.href = '/api/auth/profile'; }}, 1000);
                         }} else if (data && data.success && data.data && data.data.requiresTwoFactor) {{
                             // Handle 2FA redirection or display
                             document.getElementById('statusDiv').innerHTML = `<p class=""info-box"">${{data.message}}. Please complete the next step.</p>`;
                             // Example: Redirect or show specific 2FA form based on data.data.twoFactorType
                             if (data.data.twoFactorType === 'totp') {{
                                // show TOTP form or redirect
                             }} else if (data.data.twoFactorType === 'webauthn') {{
                                // show WebAuthn prompt or redirect
                             }}
                             // Re-enable button for now, adjust flow as needed
                             document.getElementById('loginButton').disabled = false;

                         }} else if (data) {{
                            document.getElementById('statusDiv').innerHTML = `<div class=""error-message"">${{data.message || 'Ошибка входа'}}</div>`;
                            document.getElementById('loginButton').disabled = false;
                         }} else {{
                             // Handle cases where data is null or undefined after JSON parsing attempt
                            document.getElementById('statusDiv').innerHTML = `<div class=""error-message"">Неожиданный ответ от сервера.</div>`;
                            document.getElementById('loginButton').disabled = false;
                         }}
                    }})
                    .catch(error => {{
                        console.error('Login error:', error);
                        document.getElementById('statusDiv').innerHTML = `<div class=""error-message"">Ошибка: ${{error.message || 'Неизвестная ошибка'}}</div>`;
                        document.getElementById('loginButton').disabled = false;
                    }});
                    return false;
                }}
                document.getElementById('loginForm').addEventListener('keypress', function(event) {{
                    if (event.key === 'Enter') {{ event.preventDefault(); submitLoginForm(); }}
                }});
            </script>
        ");

