        // Updated RenderWebAuthnRegistration with Yandex styling
        private string RenderWebAuthnRegistration(string options) => string.Format(BaseHtmlTemplate, "Регистрация ключа безопасности - BRU AVTOPARK", $@"
             <div class=""card"">
                 <div class=""card-header""><h1>Регистрация ключа безопасности</h1></div>
                 <div class=""card-body"">
                    <div class=""info-box"">
                        <p>Зарегистрируйте ваш ключ безопасности или биометрическую аутентификацию (отпечаток пальца, лицо) для входа без пароля.</p>
                    </div>
                    <div id=""options"" data-options='{options}' class=""hidden""></div> {/* Use single quotes for attribute value */}
                    <div class=""flex flex-col items-center gap-4 my-4"">
                        <div id=""status"" class=""text-center"">
                            <p class=""text-muted"">Нажмите кнопку ниже, чтобы зарегистрировать ключ.</p>
                        </div>
                        <button onclick=""registerWebAuthn()"" id=""registerButton"" class=""btn"">Зарегистрировать ключ</button>
                        <div id=""loader"" class=""loader hidden"" style=""margin-top: 16px;""></div>
                    </div>
                 </div>
                  <div class=""card-footer text-center"">
                    <a href=""/api/auth/profile"" class=""link"">Назад в профиль</a>
                 </div>
            </div>
            <script>
                // Existing WebAuthn registration script remains the same
                async function registerWebAuthn() {{
                     try {{
                        document.getElementById('registerButton').disabled = true;
                        document.getElementById('loader').classList.remove('hidden');
                        document.getElementById('status').innerHTML = '<p class=""text-muted"">Следуйте инструкциям браузера для регистрации ключа...</p>';
                        const optionsJson = document.getElementById('options').dataset.options;
                        const options = JSON.parse(optionsJson);

                        // Convert challenge, user.id, and excludeCredentials.id from Base64Url to ArrayBuffer
                        options.publicKey.challenge = base64UrlToArrayBuffer(options.publicKey.challenge);
                        options.publicKey.user.id = base64UrlToArrayBuffer(options.publicKey.user.id);
                        if (options.publicKey.excludeCredentials) {{
                            options.publicKey.excludeCredentials.forEach(cred => {{
                                cred.id = base64UrlToArrayBuffer(cred.id);
                            }});
                        }}
                        // Ensure Relying Party (rp) is set if needed by the library/browser
                        // options.publicKey.rp = {{ id: window.location.hostname, name: 'BRU AVTOPARK' }}; // Example

                        const credential = await navigator.credentials.create({{ publicKey: options.publicKey }});

                         const credentialResponse = {{
                            id: credential.id,
                            rawId: arrayBufferToBase64(credential.rawId),
                            type: credential.type,
                            response: {{
                                attestationObject: arrayBufferToBase64(credential.response.attestationObject),
                                clientDataJSON: arrayBufferToBase64(credential.response.clientDataJSON),
                                authenticatorData: credential.response.authenticatorData ? arrayBufferToBase64(credential.response.authenticatorData) : null,
                                transports: credential.response.getTransports ? credential.response.getTransports() : []
                            }},
                            clientExtensionResults: credential.getClientExtensionResults()
                        }};

                        const token = localStorage.getItem('auth_token'); // Get JWT token
                        const response = await fetch('/api/auth/webauthn/register/complete', {{
                            method: 'POST',
                            headers: {{
                                'Content-Type': 'application/json',
                                'Authorization': `Bearer ${{token}}` // Add authorization header
                             }},
                            body: JSON.stringify({{ attestationResponse: credentialResponse }})
                        }});

                        if (response.ok) {{
                            document.getElementById('status').innerHTML = '<p class=""success-message"">Ключ безопасности успешно зарегистрирован!</p>';
                            setTimeout(() => {{ window.location.href = '/api/auth/profile'; }}, 1500);
                        }} else {{
                             const errorText = await response.text(); // Get raw text first
                             let errorMsg = 'Регистрация не удалась';
                             try {{
                                 const errorJson = JSON.parse(errorText);
                                 errorMsg = errorJson.message || errorMsg;
                             }} catch (e) {{
                                 errorMsg = errorText || errorMsg; // Use raw text if not JSON
                             }}
                            throw new Error(errorMsg);
                        }}
                    }} catch (error) {{
                        console.error('WebAuthn registration failed:', error);
                        document.getElementById('status').innerHTML = `<p class=""error-message"">Не удалось зарегистрировать ключ: ${{error.message || error}}</p>`;
                    }} finally {{
                        document.getElementById('registerButton').disabled = false;
                        document.getElementById('loader').classList.add('hidden');
                    }}
                }}
                 // Helper function to convert Base64Url to ArrayBuffer
                function base64UrlToArrayBuffer(base64Url) {{
                    const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
                    const binaryString = atob(base64);
                    const len = binaryString.length;
                    const bytes = new Uint8Array(len);
                    for (let i = 0; i < len; i++) {{
                        bytes[i] = binaryString.charCodeAt(i);
                    }}
                    return bytes.buffer;
                }}
                // Helper function to convert ArrayBuffer to Base64 string (already provided)
                 function arrayBufferToBase64(buffer) {{
                    let binary = '';
                    const bytes = new Uint8Array(buffer);
                    const len = bytes.byteLength;
                    for (let i = 0; i < len; i++) {{
                        binary += String.fromCharCode(bytes[i]);
                    }}
                    return btoa(binary);
                }}
            </script>
            <style> .hidden {{ display: none; }} </style>");

