        private bool IsBrowserRequest()
        {
            var accept = Request.Headers.Accept.ToString().ToLower();
            // Prioritize html but allow */* as browsers often send it. Exclude JSON explicitly.
            return (accept.Contains("text/html") || accept.Contains("*/*")) && !accept.Contains("application/json");
        }

