        [HttpPost("login")]
        [AllowAnonymous]
        public async Task<IActionResult> Login([FromForm] LoginRequest request) // Prefer FromForm for typical web logins
        {
             // Handle potential JSON body if content type indicates it
            if (Request.ContentType?.Contains("application/json", StringComparison.OrdinalIgnoreCase) == true &&
                !string.IsNullOrEmpty(request.Username) && !string.IsNullOrEmpty(request.Password)) // Basic check if FromForm worked
            {
                 // If FromForm binding failed but it looks like JSON, try reading JSON
                 // This part needs careful handling or separate endpoints might be cleaner
                 // For simplicity, we assume FromForm works for typical browser posts
                 // and API clients send correct Content-Type and body.
            }


            var result = await ProcessLoginRequest(request);

            if (result is UnauthorizedObjectResult || result is BadRequestObjectResult)
            {
                if (IsBrowserRequest())
                {
                    string errorMessage = "Неверные учетные данные"; // Default
                    if (result is ObjectResult objResult && objResult.Value is ApiResponse<object> apiResponse)
                    {
                        errorMessage = apiResponse.Message ?? errorMessage;
                    }
                     return Redirect($"/api/auth/login?error={Uri.EscapeDataString(errorMessage)}");
                }
                else // API request
                {
                    return result; // Return the Unauthorized/BadRequest result directly
                }
            }
             else if (result is OkObjectResult okResult && okResult.Value is ApiResponse<LoginResponse> loginResponse) // Standard Login Success
            {
                 if (IsBrowserRequest())
                 {
                    // Redirect to success page for browser, passing token
                    return Redirect($"/api/auth/success?token={Uri.EscapeDataString(loginResponse.Data!.Token)}");
                 }
                 else // API request
                 {
                     return Ok(loginResponse); // Return JSON response for API
                 }
            }
             else if (result is OkObjectResult ok2faResult && ok2faResult.Value is ApiResponse<TwoFactorResponse> twoFactorResponse) // 2FA Required
            {
                 if (IsBrowserRequest())
                 {
                     // How to handle 2FA in browser? Redirect to a specific 2FA page?
                     // Or maybe the JS in login form should handle this response?
                     // For now, let's redirect to login with a message (could be improved)
                     return Redirect($"/api/auth/login?message={Uri.EscapeDataString(twoFactorResponse.Message)}&type={twoFactorResponse.Data?.TwoFactorType}&tempToken={Uri.EscapeDataString(twoFactorResponse.Data?.TempToken ?? "")}"); // Pass necessary info
                 }
                 else // API request
                 {
                      return Ok(twoFactorResponse); // Return JSON for API to handle 2FA step
                 }
            }
             else // Handle other potential results if necessary
            {
                 _logger.LogWarning("Login endpoint resulted in an unexpected result type: {ResultType}", result.GetType().Name);
                 if (IsBrowserRequest()) {
                      return Redirect($"/api/auth/login?error={Uri.EscapeDataString("Произошла непредвиденная ошибка")}");
                 } else {
                     return StatusCode(500, new ApiResponse<object> { Success = false, Message = "Unexpected server error during login." });
                 }
            }
        }


        // IsAdmin and HasPermission methods remain unchanged internally

        protected bool IsAdmin()
        {
            try
            {
                var authHeader = Request.Headers["Authorization"].ToString();
                if (string.IsNullOrEmpty(authHeader) || !authHeader.StartsWith("Bearer "))
                {
                    Log.Warning("Missing or invalid Authorization header");
                    return false;
                }

                var token = authHeader.Substring("Bearer ".Length);
                var tokenHandler = new JwtSecurityTokenHandler();
                var jwtToken = tokenHandler.ReadJwtToken(token);

                // Check primary role first (highest priority role)
                var primaryRoleClaim = jwtToken.Claims.FirstOrDefault(c => c.Type == "primary_role");
                if (primaryRoleClaim?.Value == "1") // Admin role has legacy ID 1
                {
                    return true;
                }

                // Fallback to checking all role claims
                var roleClaims = jwtToken.Claims.Where(c => c.Type == "role");
                return roleClaims.Any(c => c.Value == "1");
            }
            catch (Exception ex)
            {
                Log.Error(ex, "Error checking admin status");
                return false;
            }
        }

        protected bool HasPermission(string permissionName)
        {
            try
            {
                var authHeader = Request.Headers["Authorization"].ToString();
                if (string.IsNullOrEmpty(authHeader) || !authHeader.StartsWith("Bearer "))
                {
                    Log.Warning("Missing or invalid Authorization header");
                    return false;
                }

                var token = authHeader.Substring("Bearer ".Length);
                var tokenHandler = new JwtSecurityTokenHandler();
                var jwtToken = tokenHandler.ReadJwtToken(token);

                var permissionClaims = jwtToken.Claims.Where(c => c.Type == "permission");
                return permissionClaims.Any(c => c.Value == permissionName);
            }
            catch (Exception ex)
            {
                Log.Error(ex, "Error checking permission: {Permission}", permissionName);
                return false;
            }
        }


        // ProcessLoginRequest remains largely the same internally, just returns the result
        private async Task<IActionResult> ProcessLoginRequest(LoginRequest request)
        {
             // Input validation (simplified check)
             if (string.IsNullOrWhiteSpace(request.Username) || string.IsNullOrWhiteSpace(request.Password))
             {
                  return BadRequest(new ApiResponse<object> { Success = false, Message = "Имя пользователя и пароль обязательны." });
             }

            try
            {
                _logger.LogInformation("Login attempt for user: {Username}", request.Username);

                // Authenticate user
                var user = await _authService.AuthenticateAsync(request.Username, request.Password);
                if (user == null)
                {
                    _logger.LogWarning("Authentication failed for user: {Username}", request.Username);
                    return Unauthorized(new ApiResponse<object> { Success = false, Message = "Неверный логин или пароль" });
                }

                var conn = _spacetimeService.GetConnection();
                var userSettings = conn.Db.UserSettings.Iter().FirstOrDefault(s => s.UserId.Equals(user.UserId));

                if (userSettings == null)
                {
                    _logger.LogWarning("User settings not found for user: {Username}, creating default settings", request.Username);
                    conn.Reducers.CreateUserSettings(user.UserId);
                    await Task.Delay(100); // Allow time for DB update
                    userSettings = conn.Db.UserSettings.Iter().FirstOrDefault(s => s.UserId.Equals(user.UserId));
                    if (userSettings == null)
                    {
                        _logger.LogError("Failed to create or retrieve user settings for {Username}", request.Username);
                        // Decide how to proceed: fail or continue without 2FA check? Let's continue for now.
                    }
                }

                 // --- 2FA Check ---
                if (userSettings != null && !request.SkipTwoFactor) // Only check if settings exist and skip isn't requested
                {
                    // TOTP Check
                    if (userSettings.TotpEnabled)
                    {
                        var tempToken = GenerateRandomToken();
                        var expiresAt = (ulong)DateTimeOffset.UtcNow.AddMinutes(10).ToUnixTimeMilliseconds();
                        conn.Reducers.CreateTwoFactorToken(user.UserId, tempToken, false, expiresAt, Request.Headers["User-Agent"].ToString(), HttpContext.Connection.RemoteIpAddress?.ToString());
                        return Ok(new ApiResponse<TwoFactorResponse>
                        {
                            Success = true, Message = "Требуется двухфакторная аутентификация",
                            Data = new TwoFactorResponse { RequiresTwoFactor = true, TwoFactorType = "totp", TempToken = tempToken }
                        });
                    }

                    // WebAuthn Check (only if TOTP is not enabled or passed)
                    if (userSettings.WebAuthnEnabled)
                    {
                        var credentials = conn.Db.WebAuthnCredential.Iter().Where(c => c.UserId.Equals(user.UserId) && c.IsActive).ToList();
                        if (credentials.Any())
                        {
                            var (success, options, _) = await _webAuthnService.GetAssertionOptionsAsync(user.Login);
                            if (success && options != null)
                            {
                                var tempToken = GenerateRandomToken();
                                var expiresAt = (ulong)DateTimeOffset.UtcNow.AddMinutes(10).ToUnixTimeMilliseconds();
                                conn.Reducers.CreateTwoFactorToken(user.UserId, tempToken, false, expiresAt, Request.Headers["User-Agent"].ToString(), HttpContext.Connection.RemoteIpAddress?.ToString());
                                return Ok(new ApiResponse<WebAuthnTwoFactorResponse> {
                                     Success = true, Message = "Требуется аутентификация WebAuthn",
                                     Data = new WebAuthnTwoFactorResponse { RequiresTwoFactor = true, TwoFactorType = "webauthn", TempToken = tempToken, Options = options }
                                 });
                            } else {
                                _logger.LogWarning("Failed to get WebAuthn assertion options for user {Username}", request.Username);
                                // Fall through to standard login if options fail? Or return error? Let's fall through for now.
                            }
                        } else {
                             _logger.LogWarning("WebAuthn enabled but no credentials found for user {Username}", request.Username);
                              // Fall through to standard login if no credentials exist? Or return error? Let's fall through.
                        }
                    }
                }

                // --- Standard Login Success ---
                var token = GenerateJwtToken(user);
                return Ok(new ApiResponse<LoginResponse>
                {
                    Success = true, Message = "Вход выполнен успешно",
                    Data = new LoginResponse
                    {
                        Token = token,
                        User = new UserDto { Id = user.LegacyUserId, Username = user.Login, Email = user.Email, PhoneNumber = user.PhoneNumber, Role = _authService.GetUserRole(user.UserId) }
                    }
                });
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error during login for user: {Username}", request.Username);
                return StatusCode(500, new ApiResponse<object> { Success = false, Message = "Произошла внутренняя ошибка сервера при входе." });
            }
        }


        // Register method remains largely unchanged internally
        [HttpPost("register")]
        [AllowAnonymous] // Allow anonymous and check manually
        public async Task<ActionResult<RegisterResponse>> Register([FromBody] RegisterRequest request)
        {
            try
            {
                _logger.LogInformation("Registration attempt for user: {Username}", request.Username);

                // Check admin status manually using JWT token
                bool isAdmin = false;
                string? token = null;

                // Check Authorization header
                if (Request.Headers.Authorization.Count > 0)
                {
                    var authHeader = Request.Headers.Authorization.ToString();
                    if (authHeader.StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase))
                    {
                        token = authHeader.Substring("Bearer ".Length).Trim();
                    }
                }

                if (!string.IsNullOrEmpty(token))
                {
                    try
                    {
                        var handler = new JwtSecurityTokenHandler();
                        var jwtToken = handler.ReadJwtToken(token);

                        // Check for admin role in claims
                        var primaryRoleClaim = jwtToken.Claims.FirstOrDefault(c => c.Type == "primary_role");
                        isAdmin = primaryRoleClaim?.Value == "1" ||
                                jwtToken.Claims.Any(c => c.Type == "role" && c.Value == "1");
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError(ex, "Error validating JWT token for registration");
                        // Continue with isAdmin = false
                    }
                }

                if (!isAdmin)
                {
                    _logger.LogWarning("Unauthorized attempt to register a user without admin privileges");
                    return StatusCode(403, new ApiResponse<object>
                    {
                        Success = false,
                        Message = "Administrator privileges required for user registration"
                    });
                }

                // Check if user already exists
                var existingUser = await _userService.GetUserByLoginAsync(request.Username);
                if (existingUser != null)
                {
                    return BadRequest(new ApiResponse<object>
                    {
                        Success = false,
                        Message = "Username already exists"
                    });
                }

                // Check if role is valid - only admins can create admins
                if (request.Role == 1 && !isAdmin)
                {
                    return BadRequest(new ApiResponse<object>
                    {
                        Success = false,
                        Message = "Only administrators can create administrator accounts"
                    });
                }

                // Register user - pass the identity from the token to ensure proper authorization
                string? identityFromToken = null;
                if (!string.IsNullOrEmpty(token))
                {
                    var handler = new JwtSecurityTokenHandler();
                    var jwtToken = handler.ReadJwtToken(token);
                    identityFromToken = jwtToken.Claims.FirstOrDefault(c => c.Type == "identity")?.Value;
                }

                try
                {
                    // Register user
                    var success = await _authService.RegisterAsync(
                        request.Username,
                        request.Password,
                        request.Role,
                        request.Email,
                        request.PhoneNumber
                    );

                    if (!success)
                    {
                        return BadRequest(new ApiResponse<object>
                        {
                            Success = false,
                            Message = "Failed to register user"
                        });
                    }
                }
                catch (Exception ex)
                {
                    // Check if the error is from SpacetimeDB role assignment
                    if (ex.Message?.Contains("Unauthorized") == true ||
                        ex.InnerException?.Message?.Contains("Unauthorized") == true)
                    {
                        _logger.LogWarning("Role assignment failed due to authorization: {Error}", ex.Message);

                        // Check if the user was actually created despite the role error
                        var newUser = await _userService.GetUserByLoginAsync(request.Username);
                        if (newUser != null)
                        {
                            return Ok(new ApiResponse<RegisterResponse>
                            {
                                Success = true,
                                Message = "User created but could not assign requested role. Default user role applied.",
                                Data = new RegisterResponse
                                {
                                    User = new UserDto
                                    {
                                        Id = newUser.LegacyUserId,
                                        Username = newUser.Login,
                                        Email = newUser.Email,
                                        PhoneNumber = newUser.PhoneNumber,
                                        Role = _authService.GetUserRole(newUser.UserId)
                                    }
                                }
                            });
                        }

                        return BadRequest(new ApiResponse<object>
                        {
                            Success = false,
                            Message = "User creation succeeded but role assignment failed. Try logging in to SpacetimeDB directly to assign a role."
                        });
                    }

                    // For other errors, rethrow to be caught by outer catch
                    throw;
                }

                // Get the newly created user
                var newlyCreatedUser = await _userService.GetUserByLoginAsync(request.Username);
                if (newlyCreatedUser == null)
                {
                    return StatusCode(500, new ApiResponse<object>
                    {
                        Success = false,
                        Message = "User was created but could not be retrieved"
                    });
                }

                _logger.LogInformation("User {Username} registered successfully", request.Username);

                return Ok(new ApiResponse<RegisterResponse>
                {
                    Success = true,
                    Message = "User registered successfully",
                    Data = new RegisterResponse
                    {
                        User = new UserDto
                        {
                            Id = newlyCreatedUser.LegacyUserId,
                            Username = newlyCreatedUser.Login,
                            Email = newlyCreatedUser.Email,
                            PhoneNumber = newlyCreatedUser.PhoneNumber,
                            Role = _authService.GetUserRole(newlyCreatedUser.UserId)
                        }
                    }
                });
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error during registration for user: {Username}", request.Username);
                return StatusCode(500, new ApiResponse<object>
                {
                    Success = false,
                    Message = "An error occurred during registration"
                });
            }
        }


