        #region TOTP (Time-based One-Time Password)

        // TotpSetup, VerifyTotp, DisableTotp, ValidateTotp methods remain largely unchanged internally
        // The key change is returning Content(RenderTotpSetup(...), "text/html") for browser requests.

        [HttpGet("totp/setup")]
        [Authorize]
        public async Task<IActionResult> TotpSetup()
        {
            try
            {
                var userId = GetUserIdentity(); // Assume this correctly gets Identity from JWT
                if (userId == null) return Unauthorized(...);

                var user = await GetUserByIdentityAsync(userId);
                if (user == null) return NotFound(...);

                var result = await _totpService.SetupTotpAsync(userId.Value, user.Login);
                if (!result.success || result.secretKey == null || result.qrCodeUri == null)
                {
                    // Handle error for API and browser
                    var errorResponse = new ApiResponse<object> { Success = false, Message = result.errorMessage ?? "Failed to set up TOTP" };
                    if (IsBrowserRequest()) return Content(RenderErrorPage(errorResponse.Message), "text/html"); // Redirect to a generic error page perhaps?
                    return BadRequest(errorResponse);
                }

                if (IsBrowserRequest())
                {
                    // Pass QR code URI and Secret Key to the HTML template
                    return Content(RenderTotpSetup(result.qrCodeUri, result.secretKey), "text/html");
                }

                // API response
                return Ok(new ApiResponse<TotpSetupResponse>
                {
                    Success = true, Message = "TOTP setup initialized",
                    Data = new TotpSetupResponse { SecretKey = result.secretKey, QrCodeUri = result.qrCodeUri }
                });
            }
            catch (Exception ex)
            {
                 _logger.LogError(ex, "Error setting up TOTP");
                 var errorResponse = new ApiResponse<object> { Success = false, Message = "An error occurred while setting up TOTP" };
                  if (IsBrowserRequest()) return Content(RenderErrorPage(errorResponse.Message), "text/html");
                 return StatusCode(500, errorResponse);
            }
        }

        [HttpPost("totp/verify")]
        [Authorize] // Should be authorized as they initiated setup
        public async Task<IActionResult> VerifyTotp([FromForm] VerifyTotpRequest request) // Use FromForm for browser submission
        {
            try
            {
                 var userId = GetUserIdentity();
                 if (userId == null) return Unauthorized(new ApiResponse<object> { Success = false, Message = "Пользователь не аутентифицирован" });

