        [HttpPost("totp/validate")]
        [AllowAnonymous] // Temp token used for authorization here
        public async Task<ActionResult<ValidateTotpResponse>> ValidateTotp([FromBody] ValidateTotpRequest request)
        {
            try
            {
                if (!ModelState.IsValid) return BadRequest(...);

                var conn = _spacetimeService.GetConnection();
                var twoFactorToken = conn.Db.TwoFactorToken.Iter().FirstOrDefault(t => t.Token == request.TempToken && !t.IsUsed && t.ExpiresAt > (ulong)DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()); // Check expiry

                 if (twoFactorToken == null) return BadRequest(new ApiResponse<object> { Success = false, Message = "Недействительный или истекший токен" });

                var user = conn.Db.UserProfile.Iter().FirstOrDefault(u => u.UserId.Equals(twoFactorToken.UserId));
                if (user == null) return BadRequest(new ApiResponse<object> { Success = false, Message = "Пользователь не найден" });

                var totpSecret = conn.Db.TotpSecret.Iter().FirstOrDefault(t => t.UserId.Equals(user.UserId) && t.IsActive);
                if (totpSecret == null) return BadRequest(new ApiResponse<object> { Success = false, Message = "TOTP не настроен" });

                var isValid = _totpService.VerifyTotpCode(totpSecret.Secret, request.Code);
                 if (!isValid) return BadRequest(new ApiResponse<object> { Success = false, Message = "Неверный код" });

                 // Mark token as used - This reducer needs to exist or be implemented
                 // Assuming UpdateTwoFactorToken exists and sets IsUsed to true
                 conn.Reducers.UpdateTwoFactorToken(twoFactorToken.Id, twoFactorToken.UserId, twoFactorToken.Token, true, twoFactorToken.ExpiresAt);

                var token = GenerateJwtToken(user);

                 // Decide API vs Browser response
                 if (IsBrowserRequest()) {
                     // Redirect to success page, passing the final JWT token
                     return Redirect($"/api/auth/success?token={Uri.EscapeDataString(token)}");
                 }

                return Ok(new ApiResponse<ValidateTotpResponse>
                {
                    Success = true, Message = "Проверка TOTP успешна",
                    Data = new ValidateTotpResponse { Token = token, User = new UserDto { ... } } // Populate UserDto
                });
            }
            catch (Exception ex)
            {
                 _logger.LogError(ex, "Error validating TOTP");
                 var errorResponse = new ApiResponse<object> { Success = false, Message = "Произошла ошибка при проверке TOTP" };
                 // How to handle browser error here? Maybe redirect to login with error
                 if(IsBrowserRequest()) return Redirect($"/api/auth/login?error={Uri.EscapeDataString(errorResponse.Message)}");
                 return StatusCode(500, errorResponse);
            }
        }


