         // Modified RenderQrLogin to accept deviceId
        private string RenderQrLogin(string qrCodeBase64, string deviceId) => string.Format(BaseHtmlTemplate, "Вход по QR-коду - BRU AVTOPARK", $@"
             <div class=""card"">
                 <div class=""card-header""><h1>Вход по QR-коду</h1></div>
                 <div class=""card-body text-center"">
                    <div class=""info-box"">
                        <p>Отсканируйте QR-код мобильным приложением, чтобы войти.</p>
                    </div>
                    <div class=""qr-code"">
                        <img src=""data:image/png;base64,{qrCodeBase64}"" alt=""QR-код для входа"">
                    </div>
                    <div id=""status"" class=""text-center my-4"">
                        <p class=""text-muted"">Ожидание сканирования...</p>
                        <div class=""loader mt-4""></div>
                    </div>
                 </div>
                  <div class=""card-footer text-center"">
                       <a href=""/api/auth/login"" class=""link"">Другие способы входа</a>
                 </div>
            </div>
            <script>
                 const currentDeviceId = '{deviceId}'; // Use the passed deviceId

                 function checkLoginStatus(deviceIdToCheck) {{
                     fetch(`/api/auth/qr/direct/check?deviceId=${{encodeURIComponent(deviceIdToCheck)}}`)
                        .then(response => response.json())
                        .then(data => {{
                            if (data.success && data.data && data.data.token) {{
                                document.getElementById('status').innerHTML = '<p class=""success-message"">Вход успешен! Перенаправление...</p>';
                                localStorage.setItem('auth_token', data.data.token);
                                setTimeout(() => {{
                                    window.location.href = `/api/auth/success?token=${{encodeURIComponent(data.data.token)}}`;
                                }}, 1000);
                            }} else {{
                                // Check if the component is still mounted/visible before polling again
                                if (document.getElementById('status')) {{
                                     setTimeout(() => checkLoginStatus(deviceIdToCheck), 2000);
                                }}
                            }}
                        }})
                        .catch(error => {{
                            console.error('Error checking login status:', error);
                             if (document.getElementById('status')) {{
                                 document.getElementById('status').innerHTML = `<p class=""error-message"">Ошибка проверки статуса: ${{error.message || 'Unknown error'}}</p><button onclick=""checkLoginStatus(currentDeviceId)"" class=""btn btn-secondary mt-2"">Попробовать снова</button>`;
                                // Consider stopping polling after persistent errors
                             }}
                        }});
                }}

                 if (currentDeviceId) {{
                     checkLoginStatus(currentDeviceId);
                 }} else {{
                      if (document.getElementById('status')) {{
                          document.getElementById('status').innerHTML = '<p class=""error-message"">Не удалось получить ID устройства для проверки.</p>';
                      }}
                 }}
            </script>");


