        // AuthorizeCallback handles the form submission from RenderOAuthLoginForm
        [HttpPost("connect/authorize/callback")]
        [AllowAnonymous]
        public async Task<IActionResult> AuthorizeCallback([FromForm] AuthorizeCallbackRequest request)
        {
             try
             {
                 var originalRequest = _cache.Get<OpenIdConnectRequest>($"oidc_request_{request.RequestId}");
                 if (originalRequest == null)
                 {
                    // Need to render an error page if request expired/invalid
                     return Content(RenderErrorPage("Сессия авторизации истекла или недействительна."), "text/html");
                 }

                 var user = await _authService.AuthenticateAsync(request.Username, request.Password);
                 if (user == null)
                 {
                     // Render the OAuth login form again with an error message
                    var clientName = await GetClientDisplayNameFromRequest(originalRequest); // Helper needed
                     return Content(RenderOAuthLoginForm(request.RequestId, clientName, originalRequest.Scope.Split(' '), "Неверный логин или пароль"), "text/html");
                 }

                 // User authenticated, now generate authorization code
                 var code = GenerateRandomToken(); // Need a secure random string generator
                 _cache.Set($"auth_code_{code}", new AuthorizationCodeData
                 {
                     UserId = user.LegacyUserId,
                     Scopes = originalRequest.Scope.Split(' '),
                     RedirectUri = originalRequest.RedirectUri,
                     ClientId = originalRequest.ClientId // Store client_id for token endpoint validation
                 }, TimeSpan.FromMinutes(5));

                 // Redirect back to the client's redirect_uri
                 var redirectUrl = new UriBuilder(originalRequest.RedirectUri);
                 var query = System.Web.HttpUtility.ParseQueryString(redirectUrl.Query);
                 query["code"] = code;
                 query["state"] = originalRequest.State;
                 redirectUrl.Query = query.ToString();

                 return Redirect(redirectUrl.ToString());
             }
             catch (Exception ex)
             {
                 _logger.LogError(ex, "Error processing authorization callback for request ID: {RequestId}", request.RequestId);
                 return Content(RenderErrorPage("Произошла ошибка при обработке авторизации."), "text/html");
             }
        }

         // Helper to get client name for error rendering in callback
        private async Task<string> GetClientDisplayNameFromRequest(OpenIdConnectRequest oidcRequest)
        {
             if (oidcRequest == null) return "Неизвестное приложение";
             var (clientSuccess, application, _) = await _openIdConnectService.GetApplicationByClientIdAsync(oidcRequest.ClientId);
             if (clientSuccess && application != null) {
                 return await GetDisplayNameAsync(application) ?? oidcRequest.ClientId;
