        [HttpGet("connect/userinfo")]
        [Authorize] // Requires a valid Access Token (Bearer token)
        public async Task<ActionResult<UserInfoResponse>> UserInfo()
        {
            // ... existing userinfo logic ...
            // This endpoint returns JSON, no HTML rendering
             try
             {
                  var userId = GetUserIdentity(); // Get Identity from Bearer token claims
                  if (userId == null) return Unauthorized(new { error = "invalid_token", /*...*/ });

                  var user = await GetUserByIdentityAsync(userId);
                   if (user == null) return NotFound(new { error = "invalid_token", /*...*/ });

                  // Retrieve claims based on scopes granted in the token
                  // Example:
                 var claimsPrincipal = User; // Get ClaimsPrincipal from HttpContext
                 var allowedScopes = claimsPrincipal.FindAll("scope").Select(c => c.Value).ToList();

                  var userInfo = new UserInfoResponse { Sub = user.LegacyUserId.ToString() };

                  if (allowedScopes.Contains("profile")) {
                       userInfo.Name = user.Login; // Or a separate display name field
                       userInfo.PreferredUsername = user.Login;
                       // Add other profile claims like picture, website, gender, birthdate, etc. if available and requested
                  }
                  if (allowedScopes.Contains("email")) {
                       userInfo.Email = user.Email;
                       userInfo.EmailVerified = (bool)user.EmailConfirmed; // Cast needed?
                  }
                  if (allowedScopes.Contains("phone")) {
                      userInfo.PhoneNumber = user.PhoneNumber;
                      // userInfo.PhoneNumberVerified = user.PhoneNumberConfirmed; // Assuming this exists
                  }
                  if (allowedScopes.Contains("roles")) {
                       var conn = _spacetimeService.GetConnection();
                       userInfo.Roles = conn.Db.UserRole.Iter()
                           .Where(ur => ur.UserId.Equals(userId))
                           .Join(conn.Db.Role.Iter(), ur => ur.RoleId, r => r.RoleId, (ur, r) => r.Name)
                           .ToList();
                  }

                  return Ok(userInfo);
             }
             catch (Exception ex)
             {
                  _logger.LogError(ex, "Error getting user info");
                  return StatusCode(500, new { error = "server_error", /*...*/ });
             }
        }


