        #region Helper Methods

        // GenerateJwtToken, GetUserIdentity, GenerateRandomToken, GetUserByIdentityAsync remain unchanged
        // OIDC helper methods (GetClientIdAsync, etc.) remain placeholders as their implementation depends on IOpenIdConnectService

        private string GenerateJwtToken(UserProfile userProfile)
        {
            var tokenHandler = new JwtSecurityTokenHandler();
            var keyString = _configuration["JwtSettings:Secret"] ??
                throw new InvalidOperationException("JWT secret is not configured");

            // Ensure the key is at least 32 bytes (HS256 needs >= 256 bits)
            var keyBytes = Encoding.UTF8.GetBytes(keyString);
            if (keyBytes.Length < 32)
            {
                 // Pad or throw error - padding is simpler but less secure if the original key is weak
                 // For HS256, 32 bytes (256 bits) is common. For HS512, 64 bytes (512 bits).
                 _logger.LogWarning("JWT Secret is less than 32 bytes. Padding key. Consider using a longer secret.");
                 var paddedKey = new byte[32];
                 Buffer.BlockCopy(keyBytes, 0, paddedKey, 0, keyBytes.Length);
                 keyBytes = paddedKey;
            }
            // Optionally truncate if too long for the specific algorithm (e.g., HS512 typically uses 64 bytes)
            // else if (keyBytes.Length > 64) { Array.Resize(ref keyBytes, 64); }


            var key = new SymmetricSecurityKey(keyBytes);
            var expirationMinutes = double.Parse(_configuration["JwtSettings:ExpirationInMinutes"] ?? "120");

            var conn = _spacetimeService.GetConnection();

            // Get user's roles
            var userRoles = conn.Db.UserRole.Iter()
                .Where(ur => ur.UserId.Equals(userProfile.UserId))
                .Select(ur => ur.RoleId)
                .ToList();

            // Get role details (including legacy ID and name)
            var roles = conn.Db.Role.Iter()
                .Where(r => userRoles.Contains(r.RoleId) && r.IsActive)
                .ToList();

             // Get permissions associated with these roles
             var rolePermissions = conn.Db.RolePermission.Iter()
                 .Where(rp => userRoles.Contains(rp.RoleId))
                 .Select(rp => rp.PermissionId)
                 .Distinct()
                 .ToList();

             // Get permission names
             var permissions = conn.Db.Permission.Iter()
                 .Where(p => rolePermissions.Contains(p.PermissionId) && p.IsActive)
                 .Select(p => p.Name) // Select only the name
                 .ToList();


            // Create claims
            var claims = new List<Claim>
                {
                     new Claim(JwtRegisteredClaimNames.Sub, userProfile.UserId.ToString()), // Use SpacetimeDB Identity as standard sub
                     new Claim(JwtRegisteredClaimNames.Name, userProfile.Login),
                     new Claim(JwtRegisteredClaimNames.Email, userProfile.Email ?? string.Empty), // Include email if present
                     new Claim("phone_number", userProfile.PhoneNumber ?? string.Empty), // Include phone if present
                     new Claim("legacy_user_id", userProfile.LegacyUserId.ToString()), // Custom claim for legacy ID
                     new Claim("xuid", userProfile.Xuid.ToString() ?? "0") // Custom claim for XUID
                };

             // Add role claims (both name and legacy ID)
             foreach (var role in roles)
             {
                 claims.Add(new Claim(ClaimTypes.Role, role.Name)); // Standard role claim using Name
                 claims.Add(new Claim("role_id", role.LegacyRoleId.ToString())); // Custom claim for legacy role ID
             }

             // Add permission claims
             foreach (var permissionName in permissions)
             {
                 claims.Add(new Claim("permission", permissionName)); // Custom permission claim
             }

             // Add highest priority role claim (using legacy ID for backward compatibility with IsAdmin checks)
             var highestPriorityRole = roles.OrderByDescending(r => r.Priority).FirstOrDefault();
             if (highestPriorityRole != null)
             {
                 claims.Add(new Claim("primary_role", highestPriorityRole.LegacyRoleId.ToString()));
             }


            var tokenDescriptor = new SecurityTokenDescriptor
            {
                Subject = new ClaimsIdentity(claims),
                Expires = DateTime.UtcNow.AddMinutes(expirationMinutes),
                // Issuer = _configuration["JwtSettings:Issuer"], // Optional: Add if configured
                // Audience = _configuration["JwtSettings:Audience"], // Optional: Add if configured
                SigningCredentials = new SigningCredentials(key, SecurityAlgorithms.HmacSha256Signature) // Ensure algorithm matches key size expectations
            };

            var token = tokenHandler.CreateToken(tokenDescriptor);
            return tokenHandler.WriteToken(token);
        }

        private Identity? GetUserIdentity()
        {
             // Prioritize 'sub' claim (standard JWT subject) which we set to SpacetimeDB Identity
             var subClaim = User.FindFirst(ClaimTypes.NameIdentifier) ?? User.FindFirst("sub");
             if (subClaim != null && Identity.TryParse(subClaim.Value, out var userIdentity))
             {
                 return userIdentity;
             }

             // Fallback to custom 'identity' claim if needed for legacy reasons
             var identityClaim = User.FindFirst("identity");
             if (identityClaim != null && Identity.TryParse(identityClaim.Value, out userIdentity))
             {
                 return userIdentity;
             }

             // Fallback to trying legacy ID (less ideal)
             var legacyIdClaim = User.FindFirst("legacy_user_id");
             if (legacyIdClaim != null && uint.TryParse(legacyIdClaim.Value, out uint legacyId))
             {
                 try {
                     var conn = _spacetimeService.GetConnection();
                     // This might be slow if called frequently
                     return conn.Db.UserProfile.Iter().FirstOrDefault(u => u.LegacyUserId == legacyId)?.UserId;
                 } catch (Exception ex) {
                      _logger.LogError(ex, "Error looking up user by legacy ID {LegacyId} during GetUserIdentity", legacyId);
                     return null;
                 }
             }


             _logger.LogWarning("Could not determine user identity from claims.");
             return null;
        }


        private string GenerateRandomToken()
        {
            using var rng = RandomNumberGenerator.Create();
            var randomBytes = new byte[32]; // 256 bits
            rng.GetBytes(randomBytes);
            // Use Base64Url encoding for tokens used in URLs
            return Base64UrlEncoder.Encode(randomBytes);
        }

        private async Task<UserProfile?> GetUserByIdentityAsync(Identity? userId)
        {
            if (userId == null) return null;
            // Add Task.Run for potentially long-running synchronous DB access if needed,
            // but SpacetimeDB C# client might be async-friendly internally. Check its docs.
            // For simplicity, assume direct access is acceptable here.
            var conn = _spacetimeService.GetConnection();
            return conn.Db.UserProfile.Iter().FirstOrDefault(u => u.UserId.Equals(userId));
        }

