         // These depend HEAVILY on how IOpenIdConnectService and the underlying
         // OpenIddict (or other OIDC library) implementation store application details.
         // The `object application` parameter needs casting to the actual type used by the service.

         private async Task<string?> GetClientIdAsync(object application) {
             // Example using Reflection (adapt property name)
             var prop = application.GetType().GetProperty("ClientId");
             return prop?.GetValue(application)?.ToString();
             // Or using OpenIddict directly (if application is an OpenIddictApplication)
             // if (application is OpenIddictApplication oidcApp) return await _applicationManager.GetClientIdAsync(oidcApp);
         }

         private async Task<string?> GetDisplayNameAsync(object application) {
             var prop = application.GetType().GetProperty("DisplayName");
             return prop?.GetValue(application)?.ToString();
             // if (application is OpenIddictApplication oidcApp) return await _applicationManager.GetDisplayNameAsync(oidcApp);
         }
         private async Task<List<string>> GetRedirectUrisAsync(object application) {
             var prop = application.GetType().GetProperty("RedirectUris"); // Adjust property name
             var value = prop?.GetValue(application);
             if (value is IEnumerable<string> uris) return uris.ToList();
              if (value is string uriString && !string.IsNullOrEmpty(uriString)) return uriString.Split(' ', StringSplitOptions.RemoveEmptyEntries).ToList(); // Handle space-separated string?
             // if (application is OpenIddictApplication oidcApp) return (await _applicationManager.GetRedirectUrisAsync(oidcApp)).ToList();
             return new List<string>();
         }
         private async Task<List<string>> GetPostLogoutRedirectUrisAsync(object application) {
              var prop = application.GetType().GetProperty("PostLogoutRedirectUris"); // Adjust property name
             var value = prop?.GetValue(application);
              if (value is IEnumerable<string> uris) return uris.ToList();
              if (value is string uriString && !string.IsNullOrEmpty(uriString)) return uriString.Split(' ', StringSplitOptions.RemoveEmptyEntries).ToList();
             // if (application is OpenIddictApplication oidcApp) return (await _applicationManager.GetPostLogoutRedirectUrisAsync(oidcApp)).ToList();
             return new List<string>();
         }
          private async Task<List<string>> GetPermissionsAsync(object application) {
             // This might map to Scopes in OIDC terms
             var prop = application.GetType().GetProperty("Permissions") ?? application.GetType().GetProperty("AllowedScopes"); // Adjust property name
             var value = prop?.GetValue(application);
              if (value is IEnumerable<string> scopes) return scopes.ToList();
             // if (application is OpenIddictApplication oidcApp) {
             //     var permissions = await _applicationManager.GetPermissionsAsync(oidcApp);
             //     // Permissions might need mapping to OIDC scope names (e.g., prf: profile)
             //     return MapPermissionsToScopes(permissions).ToList();
             // }
             return new List<string>();
          }
          private async Task<string> GetConsentTypeAsync(object application) {
             var prop = application.GetType().GetProperty("ConsentType") ?? application.GetType().GetProperty("RequireConsent"); // Adjust property name
             var value = prop?.GetValue(application);
             if (value is bool requireConsent) return requireConsent ? "explicit" : "implicit";
             // if (application is OpenIddictApplication oidcApp) return await _applicationManager.GetConsentTypeAsync(oidcApp); // OpenIddict uses strings like "explicit", "implicit", "systematic"
             return value?.ToString() ?? "implicit"; // Default
          }

