        // ProfilePage handler needs significant changes to fetch all necessary data and use the new renderer
        [HttpGet("profile")]
        [AllowAnonymous] // Allow anonymous initially to handle token checking
        public async Task<IActionResult> ProfilePage()
        {
            if (!IsBrowserRequest())
            {
                 // Return user data as JSON for API clients if authenticated, otherwise unauthorized
                 var apiUserId = GetUserIdentity();
                 if (apiUserId == null) return Unauthorized(new ApiResponse<object> { Success = false, Message = "Authentication required" });
                 var apiUser = await GetUserByIdentityAsync(apiUserId);
                 if (apiUser == null) return NotFound(new ApiResponse<object> { Success = false, Message = "User not found" });
                  // Fetch roles/permissions for API response too
                 var conn = _spacetimeService.GetConnection();
                  var apiRoles = conn.Db.UserRole.Iter().Where(ur => ur.UserId.Equals(apiUserId)).Join(conn.Db.Role.Iter(), ur => ur.RoleId, r => r.RoleId, (ur, r) => r.Name).ToList();
                  // You might want a more detailed DTO for API profile responses
                  return Ok(new ApiResponse<object> { Success = true, Data = new { user = apiUser, roles = apiRoles /* Add more data */ } });
            }

             string? token = null;
             // Token checking logic (Authorization header, Query param, localStorage script)
             if (Request.Headers.Authorization.Count > 0 && Request.Headers.Authorization.ToString().StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase)) {
                 token = Request.Headers.Authorization.ToString().Substring("Bearer ".Length).Trim();
             }
             if (string.IsNullOrEmpty(token) && Request.Query.ContainsKey("token")) {
                 token = Request.Query["token"];
             }

             if (string.IsNullOrEmpty(token)) {
                 return Content($@"
                     <script>
                         const storedToken = localStorage.getItem('auth_token');
                         if (storedToken) {{
                             window.location.href = '/api/auth/profile?token=' + encodeURIComponent(storedToken);
                         }} else {{
                              // Redirect to login, indicating the need to login for profile access
                             window.location.href = '/api/auth/login?returnUrl=/api/auth/profile';
                         }}
                     </script>
                 ", "text/html");
             }

            try
            {
                 // Validate and parse token to get user identity
                 var handler = new JwtSecurityTokenHandler();
                 if (!handler.CanReadToken(token)) return Redirect("/api/auth/login?error=Invalid token format");

                 var jwtToken = handler.ReadJwtToken(token);
                 var userIdClaimValue = jwtToken.Claims.FirstOrDefault(c => c.Type == "sub")?.Value // Use 'sub' claim
                                     ?? jwtToken.Claims.FirstOrDefault(c => c.Type == "identity")?.Value; // Fallback

                  if (userIdClaimValue == null || !Identity.TryParse(userIdClaimValue, out var userId)) {
                      return Redirect("/api/auth/login?error=Invalid token claims");
                  }


                 // Fetch all necessary data using the userId (Identity type)
                 var conn = _spacetimeService.GetConnection();
                 var user = conn.Db.UserProfile.Iter().FirstOrDefault(u => u.UserId.Equals(userId));
                 if (user == null) return Redirect("/api/auth/login?error=User not found");

                 var userSettings = conn.Db.UserSettings.Iter().FirstOrDefault(s => s.UserId.Equals(userId));
                 bool totpEnabled = userSettings?.TotpEnabled ?? false;

                 var webAuthnCredentials = conn.Db.WebAuthnCredential.Iter()
                     .Where(c => c.UserId.Equals(userId) && c.IsActive)
                     .Select(c => new WebAuthnCredentialDto {
                          Id = Convert.ToBase64String(c.CredentialId.ToArray()), // Assuming CredentialId is List<byte>
                          CreatedAt = DateTimeOffset.FromUnixTimeMilliseconds((long)c.CreatedAt).DateTime
                     })
                     .ToList();

                 var userRoleIds = conn.Db.UserRole.Iter().Where(ur => ur.UserId.Equals(userId)).Select(ur => ur.RoleId).ToList();
                 var roles = conn.Db.Role.Iter().Where(r => userRoleIds.Contains(r.RoleId) && r.IsActive).ToList();
                 var permissionIds = conn.Db.RolePermission.Iter().Where(rp => userRoleIds.Contains(rp.RoleId)).Select(rp => rp.PermissionId).Distinct().ToList();
                 var permissions = conn.Db.Permission.Iter().Where(p => permissionIds.Contains(p.PermissionId) && p.IsActive).ToList();

                 // Render the profile page with all the fetched data
                 return Content(RenderProfilePage(user, totpEnabled, webAuthnCredentials, roles, permissions), "text/html");
            }
            catch (SecurityTokenExpiredException) {
                 _logger.LogWarning("Expired token used to access profile page.");
                  if (IsBrowserRequest()) return Redirect("/api/auth/login?error=Сессия истекла, войдите снова");
                  return Unauthorized(new ApiResponse<object>{ Success = false, Message = "Token expired"});
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error loading profile page");
                 if (IsBrowserRequest()) return Redirect($"/api/auth/error?message={Uri.EscapeDataString("Ошибка загрузки профиля")}");
                 return StatusCode(500, new ApiResponse<object>{ Success = false, Message = "Error loading profile"});
            }
        }


