        // Handle WebAuthn credential deletion from profile page form
        [HttpPost("webauthn/credentials/{id}")]
        [Authorize]
        public async Task<IActionResult> RemoveWebAuthnCredentialForm(string id, [FromForm] string _method)
        {
            if (!IsBrowserRequest() || _method?.ToUpperInvariant() != "DELETE")
            {
                // If it's an API call or not DELETE, use the dedicated DELETE endpoint handler
                 if (_method?.ToUpperInvariant() == "DELETE") return await RemoveWebAuthnCredential(id);
                 return BadRequest(new ApiResponse<object>{Success = false, Message = "Invalid request method for form submission."});
            }

            // Proceed with deletion logic for browser form POST
            try
            {
                var userId = GetUserIdentity();
                if (userId == null) return Redirect("/api/auth/login?error=Требуется аутентификация"); // Redirect browser

                var result = await _webAuthnService.RemoveCredentialAsync(userId.Value, id);

                if (!result.success)
                {
                    return Redirect($"/api/auth/profile?error={Uri.EscapeDataString(result.errorMessage ?? "Не удалось удалить ключ")}");
                }
                return Redirect("/api/auth/profile?message=Ключ безопасности удален");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error removing WebAuthn credential via form");
                return Redirect($"/api/auth/profile?error={Uri.EscapeDataString("Ошибка при удалении ключа")}");
            }
        }


        // OAuthLoginPage remains largely the same as it renders RenderOAuthLoginForm
        [HttpGet("oauth/login")]
        [AllowAnonymous]
        public async Task<IActionResult> OAuthLoginPage([FromQuery] string request_id, [FromQuery] string? error = null)
        {
             if (string.IsNullOrEmpty(request_id)) return BadRequest("Missing request_id");

             var originalRequest = _cache.Get<OpenIdConnectRequest>($"oidc_request_{request_id}");
             if (originalRequest == null) return Content(RenderErrorPage("Сессия авторизации истекла или недействительна"), "text/html"); // Render error for browser

             var clientName = await GetClientDisplayNameFromRequest(originalRequest);
             var scopes = originalRequest.Scope.Split(' ');

             if (IsBrowserRequest())
             {
                 return Content(RenderOAuthLoginForm(request_id, clientName, scopes, error), "text/html");
             }
             // API response remains the same
             return Ok(new { client_id = originalRequest.ClientId, /* ... other details ... */ });
        }

