         // OIDC Admin Page Handlers remain largely the same, just returning the styled HTML content

         // Updated RenderRegisterForm with Yandex styling
          private string RenderRegisterForm(string? error = null, string? message = null, int? adminCheckAttempt = null, bool isAdmin = false) => string.Format(BaseHtmlTemplate, "Регистрация пользователя - BRU AVTOPARK", $@"
             <div class=""card"">
                 <div class=""card-header""><h1>Регистрация нового пользователя</h1></div>
                 <div class=""card-body"">
                     {(error != null ? $"<div class='error-message'>{System.Web.HttpUtility.HtmlEncode(error)}</div>" : "")}
                     {(message != null ? $"<div class='success-message'>{System.Web.HttpUtility.HtmlEncode(message)}</div>" : "")}

                      <div class=""info-box"">
                         <strong>Примечание:</strong> Только администраторы могут регистрировать новых пользователей.
                     </div>

                     {(!isAdmin && adminCheckAttempt.HasValue ? $@"
                         <div class=""error-message"">
                              <strong>Проверка прав администратора... (Попытка {adminCheckAttempt ?? 0}/3)</strong>
                              <p style='margin-top: 8px; font: var(--id-typography-text-s);'>Если вы администратор, но видите это сообщение, попробуйте <a href='/api/auth/logout' class='link'>выйти</a> и <a href='/api/auth/login?returnUrl=/api/auth/register' class='link'>войти</a> снова.</p>
                         </div>" : "")}

                     {(isAdmin ? $@"
                         <div class=""success-message"">
                             <strong>Вы вошли как администратор.</strong>
                         </div>" : "")}


                      <form id=""registerForm"" {(isAdmin ? "" : "style='display: none;'")}> {/* Hide form initially if not admin */}
                         <div class=""form-group"">
                             <label for=""username"">Логин</label>
                             <input type=""text"" id=""username"" name=""username"" required>
                         </div>
                         <div class=""form-group"">
                             <label for=""password"">Пароль</label>
                             <input type=""password"" id=""password"" name=""password"" required>
                         </div>
                          <div class=""form-group"">
                             <label for=""email"">Email (необязательно)</label>
                             <input type=""email"" id=""email"" name=""email"">
                         </div>
                         <div class=""form-group"">
                             <label for=""phoneNumber"">Телефон (необязательно)</label>
                             <input type=""tel"" id=""phoneNumber"" name=""phoneNumber"">
                         </div>
                         <div class=""form-group"">
                             <label for=""role"">Роль</label>
                             <select id=""role"" name=""role"" required>
                                 {/* Populate options based on available roles */}
                                 <option value=""0"">Пользователь</option>
                                 <option value=""1"">Администратор</option>
                                 <option value=""2"">Менеджер</option>
                                 <option value=""3"">Водитель</option>
                                 <option value=""4"">Кондуктор</option>
                                 <option value=""5"">Диспетчер</option>
                             </select>
                         </div>
                         <button type=""submit"" class=""btn btn-block"">Зарегистрировать</button>
                         <div id=""register-status"" class=""mt-4""></div>
                     </form>
                 </div>
                  <div class=""card-footer text-center"">
                     <a href=""/api/auth/profile"" class=""link"">Назад в профиль</a>
                 </div>
             </div>

              <script>
                 // Admin check logic
                 const isAdmin = {isAdmin.ToString().ToLowerInvariant()};
                 if (isAdmin) {{
                     document.getElementById('registerForm').style.display = 'block';
                 }} else {{
                      const attempt = {adminCheckAttempt ?? 0};
                      if (attempt > 0 && attempt < 3) {{
                         // Optionally wait before redirecting if attempts are shown
                         // setTimeout(() => {{ /* redirect logic */ }}, 2000);
                     }} else if (attempt >= 3) {{
                          // Redirect immediately if max attempts reached
                          // window.location.href = '/api/auth/login?error=Administrator+privileges+required';
                     }}
                 }}

                  // Form submission logic
                 document.getElementById('registerForm').addEventListener('submit', async (e) => {{
                     e.preventDefault();
                     const statusElement = document.getElementById('register-status');
                     statusElement.innerHTML = '<div class=""loader""></div>';
                     const formData = {{
                         username: document.getElementById('username').value,
                         password: document.getElementById('password').value,
                         email: document.getElementById('email').value || null,
                         phoneNumber: document.getElementById('phoneNumber').value || null,
                         role: parseInt(document.getElementById('role').value)
                     }};

                     try {{
                         const token = localStorage.getItem('auth_token');
                         if (!token) {{
                              // Should not happen if form is only shown to admins, but handle anyway
                             statusElement.innerHTML = '<div class=""error-message"">Ошибка аутентификации. Пожалуйста, войдите снова.</div>';
                              setTimeout(() => {{ window.location.href = '/api/auth/login?returnUrl=/api/auth/register'; }}, 2000);
                             return;
                         }}

                         const response = await fetch('/api/auth/register', {{
                             method: 'POST',
                             headers: {{ 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token }},
                             body: JSON.stringify(formData)
                         }});

                         const result = await response.json(); // Assume response is always JSON

                         if (response.ok && result.success) {{
                             statusElement.innerHTML = '<div class=""success-message"">Пользователь успешно зарегистрирован!</div>';
                             document.getElementById('registerForm').reset(); // Clear form on success
                         }} else {{
                             const errorMsg = result.message || 'Ошибка регистрации';
                             statusElement.innerHTML = '<div class=""error-message"">' + errorMsg + '</div>';
                         }}
                     }} catch (error) {{
                         console.error('Registration error:', error);
                         statusElement.innerHTML = '<div class=""error-message"">Произошла ошибка при регистрации. Попробуйте снова.</div>';
                     }}
                 }});
             </script>
         ");

         // RegisterPage handler remains largely the same internally
         [HttpGet("register")]
         [AllowAnonymous]
         public async Task<IActionResult> RegisterPage([FromQuery] string? error = null, [FromQuery] string? message = null, [FromQuery] int? attempt = null)
         {
            if (!IsBrowserRequest()) {
                 return Forbidden(new ApiResponse<object> { Success = false, Message = "Administrator privileges required. Use POST /api/auth/register for API calls." });
            }

            // Token checking logic...
            string? token = null;
             bool isAdmin = false;
             if (Request.Headers.Authorization.Count > 0 && Request.Headers.Authorization.ToString().StartsWith("Bearer ", StringComparison.OrdinalIgnoreCase)) {
                 token = Request.Headers.Authorization.ToString().Substring("Bearer ".Length).Trim();
             }
             if (string.IsNullOrEmpty(token) && Request.Query.ContainsKey("token")) {
                 token = Request.Query["token"];
             }

             if (string.IsNullOrEmpty(token)) {
                  return Content($@"<script> /* ... localStorage check and redirect to login ... */ </script>", "text/html");
             }

             // Validate admin status from token
             try {
                 var handler = new JwtSecurityTokenHandler();
                 if (!handler.CanReadToken(token)) return Redirect("/api/auth/login?error=Invalid token format");
                 var jwtToken = handler.ReadJwtToken(token);
                 var primaryRoleClaim = jwtToken.Claims.FirstOrDefault(c => c.Type == "primary_role");
                 isAdmin = primaryRoleClaim?.Value == "1" || jwtToken.Claims.Any(c => c.Type == "role" && c.Value == "1");

                  if (!isAdmin && (!attempt.HasValue || attempt.Value < 3)) {
                      int nextAttempt = (attempt ?? 0) + 1;
                      // Optionally add delay or just re-render immediately with attempt info
                      // Consider if the delay is good UX or just annoying
                      // await Task.Delay(500 * nextAttempt);
                      return Content(RenderRegisterForm(error, message, nextAttempt, false), "text/html");
                  } else if (!isAdmin) {
                       // Max attempts reached or first load without admin rights, redirect to login definitively
                      return Redirect("/api/auth/login?error=Administrator privileges required");
                  }

                 // If admin, render the form
                 return Content(RenderRegisterForm(error, message, attempt, true), "text/html");

             } catch (Exception ex) {
                  _logger.LogError(ex, "Error validating admin access for registration page");
                  return Redirect("/api/auth/login?error=Error validating admin access");
             }
        }


